<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import Dialog from 'primevue/dialog'; import InputNumber from 'primevue/inputnumber'; import InputText from 'primevue/inputtext'; import Message from 'primevue/message'; import Select from 'primevue/select'; import Tag from 'primevue/tag'
import AfeSnapshotPanel from '~/components/afe/AfeSnapshotPanel.vue'
import EstimateBreakdownChart from '~/components/charts/EstimateBreakdownChart.vue'
import PageHeader from '~/components/design-system/PageHeader.vue'
import EstimateWorkflowPanel from '~/components/workflow/EstimateWorkflowPanel.vue'
import type { EstimateAfeStatus } from '~/types/afe'
import type { CalculationResults } from '~/types/calculations'
import type { Estimate, EstimateItem } from '~/types/estimates'; import type { MasterDataRecord, RateRecord } from '~/types/masterData'
import type { EstimateWorkflowStatus } from '~/types/workflow'
definePageMeta({ middleware: 'auth' })
const id = String(useRoute().params.id); const api = useEstimates(); const master = useMasterData(); const workflowApi = useWorkflow(); const afeApi = useAfe()
const estimate = ref<Estimate | null>(null); const versionId = ref(''); const rows = ref<Array<EstimateItem & { _dirty?: boolean }>>([]); const selected = ref<EstimateItem[]>([])
const vendors = ref<MasterDataRecord[]>([]); const rates = ref<RateRecord[]>([]); const categories = ref<MasterDataRecord[]>([]); const results = ref<CalculationResults | null>(null); const workflow = ref<EstimateWorkflowStatus | null>(null); const afe = ref<EstimateAfeStatus | null>(null); const afeLoading = ref(false); const afeMessage = ref<string | null>(null); const reviewNote = ref(''); const savingReviewNote = ref(false); const calculating = ref(false); const calculationMessage = ref<string | null>(null); const assignVisible = ref(false); const assignVendor = ref<string | null>(null); const assignRate = ref<string | null>(null); const contingency = ref<number | null>(null); const escalation = ref<number | null>(null); const assumptionCategory = ref<string | null>(null); const error = ref<string | null>(null)
const versions = computed(() => estimate.value?.versions ?? []); const version = computed(() => versions.value.find(v => v.id === versionId.value));
async function load() { const [detail, vendorPage, ratePage, categoryPage] = await Promise.all([api.get(id), master.list('vendors'), master.listRates(), master.list('cost-categories')]); estimate.value = detail; vendors.value = vendorPage.items.filter(x => x.is_active); rates.value = ratePage.items.filter(x => x.is_active); categories.value = categoryPage.items; if (!versionId.value) versionId.value = detail.versions.find(v => v.version_number === detail.current_version_number)?.id ?? detail.versions[0]?.id ?? ''; selectVersion() }
async function loadVersionPanels() { if (!versionId.value) return; const [calculation, workflowStatus, afeStatus] = await Promise.all([api.results(id, versionId.value), workflowApi.status(id, versionId.value), afeApi.status(id, versionId.value)]); results.value = calculation; workflow.value = workflowStatus; afe.value = afeStatus }
function selectVersion() { rows.value = (version.value?.items ?? []).map(item => ({ ...item, _dirty: false })); selected.value = []; void loadVersionPanels().catch((caught: unknown) => { error.value = caught instanceof Error ? caught.message : 'Version status failed' }) }
function mark(row: EstimateItem & { _dirty?: boolean }) { row._dirty = true }
async function save() { const changed = rows.value.filter(row => row._dirty).map(row => ({ id: row.id, quantity: row.quantity, vendor_id: row.vendor_id, rate_id: row.rate_id, notes: row.notes })); if (changed.length) await api.updateItems(changed); await load() }
async function assign() { if (!version.value) return; await api.assign(version.value.id, selected.value.map(x => x.id), assignVendor.value, assignRate.value); assignVisible.value = false; await load() }
async function duplicateItems() { if (!version.value) return; await api.duplicateItems(version.value.id, selected.value.map(x => x.id)); await load() }
async function duplicateVersion() { await api.duplicateVersion(id, 'Alternative bulk cost build'); versionId.value = ''; await load() }
async function saveAssumption() { if (!version.value) return; await api.assumption(version.value.id, { cost_category_id: assumptionCategory.value, contingency_percent: contingency.value, escalation_percent: escalation.value }); await load() }
async function download(kind: 'export' | 'template') { if (!version.value) return; const blob = kind === 'export' ? await api.export(version.value.id) : await api.template(version.value.id); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `estimate-${kind}.xlsx`; a.click(); URL.revokeObjectURL(url) }
async function recalculate() { if (!version.value) return; calculating.value = true; calculationMessage.value = null; try { results.value = await api.calculate(id, version.value.id) } catch (caught: unknown) { calculationMessage.value = caught instanceof Error ? caught.message : 'Calculation blocked'; results.value = await api.results(id, version.value.id) } finally { calculating.value = false } }
async function addReviewComment() { if (!version.value || !reviewNote.value.trim()) return; savingReviewNote.value = true; try { await workflowApi.addComment(id, version.value.id, reviewNote.value); reviewNote.value = ''; workflow.value = await workflowApi.status(id, version.value.id) } catch (caught: unknown) { error.value = caught instanceof Error ? caught.message : 'Review note failed' } finally { savingReviewNote.value = false } }
async function createAfeBaseline() { if (!version.value) return; afeLoading.value = true; afeMessage.value = null; try { afe.value = await afeApi.createBaseline(id, version.value.id) } catch (caught: unknown) { afeMessage.value = caught instanceof Error ? caught.message : 'AFE snapshot blocked'; afe.value = await afeApi.status(id, version.value.id) } finally { afeLoading.value = false } }
onMounted(() => void load().catch(e => { error.value = e instanceof Error ? e.message : 'Load failed' }))
</script>
<template><div v-if="estimate" class="requirement-detail-page"><PageHeader :title="estimate.title" :description="`${estimate.project_code} / ${estimate.well_code} · ${estimate.code} · ${estimate.currency_code}`"><template #actions><Tag :value="results?.calculation_status ?? 'not calculated'" severity="warn" /><Button label="Recalculate" icon="pi pi-refresh" :loading="calculating" @click="recalculate" /><Button label="New version" icon="pi pi-copy" outlined @click="duplicateVersion" /></template></PageHeader><Message severity="warn" :closable="false">Rate selection is manual because automatic rate precedence is not confirmed. Financial outputs remain blocked until confirmed rules are supplied.</Message><Message v-if="calculationMessage" severity="error" :closable="false">{{ calculationMessage }}</Message><p v-if="error" class="error-copy">{{ error }}</p><div class="builder-layout"><main><div class="grid-toolbar bulk-grid-panel requirement-toolbar"><Select v-model="versionId" :options="versions" option-label="version_number" option-value="id" @change="selectVersion"><template #option="{ option }">Version {{ option.version_number }}</template><template #value="{ value }">Version {{ versions.find(v => v.id === value)?.version_number }}</template></Select><div class="grid-toolbar__actions"><Button label="Assign vendor/rate" :disabled="!selected.length" outlined @click="assignVisible = true" /><Button label="Duplicate rows" :disabled="!selected.length" text @click="duplicateItems" /><Button label="Template" text icon="pi pi-file-excel" @click="download('template')" /><Button label="Export" text icon="pi pi-download" @click="download('export')" /><Button label="Save build" icon="pi pi-save" @click="save" /></div></div><DataTable v-model:selection="selected" :value="rows" data-key="id" paginator :rows="25" show-gridlines striped-rows scrollable class="bulk-grid-panel"><Column selection-mode="multiple" /><Column field="line_number" header="#" /><Column field="catalog_item_name" header="Item"><template #body="{ data }"><strong>{{ data.catalog_item_code }}</strong><br><small>{{ data.catalog_item_name }}</small></template></Column><Column field="cost_code" header="Cost code" /><Column header="Vendor" style="min-width: 170px"><template #body="{ data }"><Select v-model="data.vendor_id" :options="vendors" option-label="name" option-value="id" show-clear filter fluid @change="mark(data)" /></template></Column><Column header="Rate" style="min-width: 170px"><template #body="{ data }"><Select v-model="data.rate_id" :options="rates.filter(rate => rate.item_id === data.catalog_item_id)" option-value="id" show-clear fluid @change="mark(data)"><template #option="{ option }">{{ option.vendor_code }} · {{ option.amount }} {{ option.currency_code }}</template></Select></template></Column><Column header="Quantity"><template #body="{ data }"><InputNumber v-model="data.quantity" :min="0" :max-fraction-digits="4" fluid @input="mark(data)" /></template></Column><Column field="unit_code" header="Unit" /><Column header="Notes"><template #body="{ data }"><InputText v-model="data.notes" fluid @input="mark(data)" /></template></Column><Column header="Calculated cost"><template #body><span class="pending-value">Pending Phase 5</span></template></Column></DataTable></main><aside class="assumptions-panel"><h3>Assumptions</h3><p>Stored for the audited calculation input; not applied until rules are confirmed.</p><label>Cost category<Select v-model="assumptionCategory" :options="categories" option-label="name" option-value="id" show-clear fluid /></label><label>Contingency %<InputNumber v-model="contingency" :min="0" :max-fraction-digits="4" fluid /></label><label>Escalation %<InputNumber v-model="escalation" :min="0" :max-fraction-digits="4" fluid /></label><Button label="Save assumption" outlined fluid @click="saveAssumption" /><div v-for="item in version?.assumptions ?? []" :key="item.id" class="assumption-chip">{{ item.cost_category_id ? 'Category' : 'Estimate' }} · C {{ item.contingency_percent ?? '—' }}% · E {{ item.escalation_percent ?? '—' }}%</div></aside></div><section class="calculation-panel"><div class="calculation-summary"><div><span>Base total</span><strong>{{ results?.base_total ?? 'Pending' }}</strong></div><div><span>Contingency</span><strong>{{ results?.contingency_total ?? 'Pending' }}</strong></div><div><span>Escalation</span><strong>{{ results?.escalation_total ?? 'Pending' }}</strong></div><div><span>Grand total</span><strong>{{ results?.grand_total ?? 'Pending' }}</strong></div></div><EstimateBreakdownChart :categories="results?.category_results ?? []" /><details v-if="results?.pending_rules.length" class="pending-rules"><summary>Pending business rules ({{ results.pending_rules.length }})</summary><ul><li v-for="rule in results.pending_rules" :key="rule">{{ rule }}</li></ul></details><div v-if="results?.calculation_runs.length" class="calculation-runs"><h3>Calculation runs</h3><div v-for="run in results.calculation_runs" :key="run.id" class="calculation-run"><Tag :value="run.status" :severity="run.status === 'completed' ? 'success' : run.status === 'blocked' ? 'warn' : 'info'" /><span>Engine {{ run.engine_version }} · Rules {{ run.rule_set_version }}</span><time>{{ new Date(run.created_at).toLocaleString() }}</time></div></div></section><EstimateWorkflowPanel v-model:note="reviewNote" :status="workflow" :saving="savingReviewNote" @add-comment="addReviewComment" /><AfeSnapshotPanel :status="afe" :loading="afeLoading" :request-message="afeMessage" @create-baseline="createAfeBaseline" /><Dialog v-model:visible="assignVisible" modal header="Bulk assign vendor and rate" :style="{ width: '500px' }"><div class="form-stack"><label>Vendor<Select v-model="assignVendor" :options="vendors" option-label="name" option-value="id" show-clear filter fluid /></label><label>Rate<Select v-model="assignRate" :options="rates.filter(rate => !assignVendor || rate.vendor_id === assignVendor)" option-value="id" show-clear fluid><template #option="{ option }">{{ option.item_code }} · {{ option.vendor_code }} · {{ option.amount }}</template></Select></label></div><template #footer><Button label="Apply to selected" @click="assign" /></template></Dialog></div></template>
